// ShaderToy Shader

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalisierte Koordinaten
    vec2 uv = fragCoord / iResolution.xy;
    uv -= 0.5; // Zentriere UV-Koordinaten
    uv.x *= iResolution.x / iResolution.y; // Bildschirmverhältnis anpassen

    // Unendlicher Zoom basierend auf der Zeit
    float zoom = pow(1.618, mod(iTime * 0.2, 10.0)); // Skaliert mit Φ
    uv *= zoom;

    // Hexagonale Rasterung
    const float sqrt3 = 1.73205080757; // √3 für Hexagon-Geometrie
    vec2 hex = vec2(uv.x, uv.y / sqrt3);

    // Hexagon-Indizes berechnen
    vec2 hIndex = floor(hex);
    vec2 hFrac = fract(hex);

    // Koordinaten zurück in den Bereich eines Hexagons transformieren
    vec2 center = hIndex + 0.5;
    float distToCenter = length(uv - center);

    // Farbwechsel basierend auf der Entfernung zum Zentrum
    vec3 color = vec3(sin(distToCenter * 10.0 + iTime) * 0.5 + 0.5,
                      sin(distToCenter * 15.0 + iTime) * 0.5 + 0.5,
                      sin(distToCenter * 20.0 + iTime) * 0.5 + 0.5);

    // Transparenz basierend auf der Entfernung
    float alpha = 0.5 + 0.5 * sin(distToCenter * 5.0 - iTime * 2.0);

    // Transparente Hexagons
    float hexShape = step(0.5, distToCenter - floor(distToCenter));
    fragColor = vec4(color, alpha * hexShape);
}
